questionvariables.text:
/* Random 3D points A and B in R^3 (keep them distinct) */
ax: rand(9)-4;  ay: rand(9)-4;  az: rand(9)-4;
bx: rand(9)-4;  by: rand(9)-4;  bz: rand(9)-4;

while (ax=bx and ay=by and az=bz) do (
  bx: rand(9)-4, by: rand(9)-4, bz: rand(9)-4
);

/* Nice display as ordered triples */
A: ntuple(ax,ay,az);
B: ntuple(bx,by,bz);

/* Distance */
dx: bx-ax; dy: by-ay; dz: bz-az;
dist2: dx^2+dy^2+dz^2;
ta: sqrt(dist2); /* teacher's answer */
